#[inline]
pub(crate) fn keysym_from_name(name: &[u8]) -> Option<u32> {
    NAME_TO_KEYSYM.iter().find_map(|entry| {
        let stored = &KEYSYM_NAMES[entry.1 as usize..];
        let stored = &stored[..stored.iter().position(|&b| b == 0)?];
        (stored == name).then_some(entry.0)
    })
}
