pub(crate) const XKB_KEYSYM_MAX_EXPLICIT: i32 = 0x1008ffb8;
pub(crate) const XKB_KEYSYM_UNICODE_OFFSET: u32 = 0x1000000;
pub(crate) const XKB_KEYSYM_UNICODE_MIN: u32 = 0x1000100;
pub(crate) const XKB_KEYSYM_UNICODE_MAX: u32 = 0x110ffff;
pub(crate) const XKB_KEYSYM_UNICODE_SURROGATE_MIN: u32 = 0x100d800;
pub(crate) const XKB_KEYSYM_UNICODE_SURROGATE_MAX: u32 = 0x100dfff;

use super::parser::istrcmp;
#[inline]
fn get_name_bytes(offset: u32) -> &'static [u8] {
    let start = offset as usize;
    let rest = &KEYSYM_NAMES[start..];
    let end = rest.iter().position(|&b| b == 0).unwrap_or(rest.len());
    &rest[..end]
}

/// Get keysym name as static string (for serialization).
/// Returns `None` if keysym is not found.
pub(crate) fn keysym_get_name(ks: u32) -> Option<&'static str> {
    if ks > XKB_KEYSYM_MAX_EXPLICIT as u32 {
        return None;
    }
    let canonical = KEYSYM_CANONICAL_NAMES
        .binary_search_by_key(&ks, |entry| entry.0)
        .map(|i| KEYSYM_CANONICAL_NAMES[i].1)
        .ok();
    let mut alpha_first: Option<u32> = None;
    for entry in NAME_TO_KEYSYM {
        if entry.0 == ks {
            alpha_first = Some(match alpha_first {
                Some(cur) => cur.min(entry.1),
                None => entry.1,
            });
        }
    }
    let name_bytes = get_name_bytes(canonical.unwrap_or(alpha_first?));
    std::str::from_utf8(name_bytes).ok()
}

fn parse_keysym_hex(s: &[u8], out: &mut u32) -> bool {
    let slice = if s.len() > 8 { &s[..8] } else { s };
    let (val, count) = super::parser::parse_hex_u32(slice);
    *out = val;
    count > 0 && s.get(count as usize).copied() == Some(0)
}
pub(crate) fn xkb_keysym_from_name(name: &[u8], flags: u32) -> Option<u32> {
    const XKB_KEYSYM_FLAGS: u32 = XKB_KEYSYM_CASE_INSENSITIVE;
    if flags & !XKB_KEYSYM_FLAGS != 0 {
        return None;
    }
    let mut val: u32 = 0;
    let icase: bool = flags & XKB_KEYSYM_CASE_INSENSITIVE != 0;
    // name includes null terminator from C buffers; get the content before null
    let name_bytes = if let Some(null_pos) = name.iter().position(|&b| b == 0) {
        &name[..null_pos]
    } else {
        name
    };
    if !icase {
        if let Some(keysym) = keysym_from_name(name_bytes) {
            return Some(keysym);
        }
    } else {
        let mut lo: i32 = 0;
        let mut hi: i32 = NAME_TO_KEYSYM.len() as i32 - 1;
        while hi >= lo {
            let mid = ((lo + hi) / 2) as usize;
            let cmp = istrcmp(name_bytes, get_name_bytes(NAME_TO_KEYSYM[mid].1));
            if cmp > 0 {
                lo = mid as i32 + 1;
            } else if cmp < 0 {
                hi = mid as i32 - 1;
            } else {
                let mut idx = mid;
                for (candidate, entry) in NAME_TO_KEYSYM.iter().enumerate().skip(mid + 1) {
                    if istrcmp(
                        get_name_bytes(entry.1),
                        get_name_bytes(NAME_TO_KEYSYM[idx].1),
                    ) == 0
                    {
                        idx = candidate;
                    } else {
                        break;
                    }
                }
                return Some(NAME_TO_KEYSYM[idx].0);
            }
        }
    }

    if name_bytes.first() == Some(&b'U') || (icase && name_bytes.first() == Some(&b'u')) {
        // Pass rest including original null terminator
        let rest_start = 1;
        let rest = &name[rest_start..];
        if !parse_keysym_hex(rest, &mut val) {
            return None;
        }
        return Some(if val > 0xff_u32 && val <= 0x10ffff_u32 {
            XKB_KEYSYM_UNICODE_OFFSET.wrapping_add(val)
        } else {
            codepoint_to_keysym(val).unwrap_or(0)
        });
    } else if name_bytes.first() == Some(&b'0')
        && (name_bytes.get(1) == Some(&b'x') || (icase && name_bytes.get(1) == Some(&b'X')))
    {
        let rest = &name[2..];
        if !parse_keysym_hex(rest, &mut val) || val > XKB_KEYSYM_MAX {
            return None;
        }
        return Some(val);
    }
    if name_bytes.starts_with(b"XF86_")
        || (icase
            && name_bytes
                .get(..5)
                .is_some_and(|s| s.eq_ignore_ascii_case(b"XF86_")))
    {
        // Convert "XF86_Foo" -> "XF86Foo" by removing the underscore
        let mut tmp_buf: Vec<u8> = Vec::with_capacity(name.len());
        tmp_buf.extend_from_slice(&name_bytes[..4]); // "XF86"
        tmp_buf.extend_from_slice(&name_bytes[5..]); // skip underscore
        tmp_buf.push(0); // null terminator
        return xkb_keysym_from_name(&tmp_buf, flags);
    }
    None
}

pub(crate) fn xkb_keysym_is_keypad(keysym: u32) -> bool {
    (XKB_KEY_KP_SPACE..=XKB_KEY_KP_EQUAL).contains(&keysym)
}

